INSERT INTO lesson (id, unit_id, name, type, content, sort_order, star_reward) VALUES
(498, 42, '你好，我叫 Mimi', 'DIALOGUE', '{"type":"DIALOGUE","scene":"新朋友见面","tip":"练习打招呼和自我介绍","items":[{"speaker":"Mimi","text":"Hello! My name is Mimi.","translation":"你好！我叫 Mimi。","scene":"新朋友见面","image":"festival/childrens-day","audio":""},{"speaker":"New Friend","text":"Hi, Mimi! I am Leo.","translation":"你好，Mimi！我是 Leo。","scene":"新朋友见面","image":"festival/childrens-day","audio":""},{"speaker":"Mimi","text":"Nice to meet you.","translation":"很高兴认识你。","scene":"新朋友见面","image":"festival/childrens-day","audio":""},{"speaker":"New Friend","text":"Nice to meet you, too!","translation":"我也很高兴认识你！","scene":"新朋友见面","image":"festival/childrens-day","audio":""}]}', 6, 3),
(499, 47, '我想要，也会拒绝', 'DIALOGUE', '{"type":"DIALOGUE","scene":"早餐桌","tip":"练习表达想要、喜欢和礼貌拒绝","items":[{"speaker":"Mimi","text":"I want an apple, please.","translation":"我想要一个苹果，谢谢。","scene":"早餐桌","image":"math/apple-1","audio":""},{"speaker":"Parent","text":"Here you are. Do you like milk?","translation":"给你。你喜欢牛奶吗？","scene":"早餐桌","image":"math/apple-1","audio":""},{"speaker":"Mimi","text":"Yes, I like milk.","translation":"是的，我喜欢牛奶。","scene":"早餐桌","image":"math/apple-1","audio":""},{"speaker":"Parent","text":"Do you want candy?","translation":"你想要糖果吗？","scene":"早餐桌","image":"math/apple-1","audio":""},{"speaker":"Mimi","text":"No, thank you.","translation":"不了，谢谢。","scene":"早餐桌","image":"math/apple-1","audio":""}]}', 6, 3),
(500, 41, '请帮帮我', 'DIALOGUE', '{"type":"DIALOGUE","scene":"家庭互助","tip":"练习请求帮助和表示感谢","items":[{"speaker":"Mimi","text":"Can you help me, please?","translation":"请问你能帮帮我吗？","scene":"家庭互助","image":"emotion/encourage","audio":""},{"speaker":"Family","text":"Of course. What do you need?","translation":"当然。你需要什么？","scene":"家庭互助","image":"emotion/encourage","audio":""},{"speaker":"Mimi","text":"Please help me find my book.","translation":"请帮我找找书。","scene":"家庭互助","image":"emotion/encourage","audio":""},{"speaker":"Family","text":"Here it is!","translation":"书在这里！","scene":"家庭互助","image":"emotion/encourage","audio":""},{"speaker":"Mimi","text":"Thank you for helping me.","translation":"谢谢你帮助我。","scene":"家庭互助","image":"emotion/encourage","audio":""}]}', 6, 3),
(501, 42, '听老师的指令', 'DIALOGUE', '{"type":"DIALOGUE","scene":"英语课堂","tip":"练习常见课堂指令","items":[{"speaker":"Teacher","text":"Please sit down.","translation":"请坐下。","scene":"英语课堂","image":"art/canvas","audio":""},{"speaker":"Mimi","text":"Okay, I am sitting down.","translation":"好的，我坐下了。","scene":"英语课堂","image":"art/canvas","audio":""},{"speaker":"Teacher","text":"Open your book and listen.","translation":"打开书，认真听。","scene":"英语课堂","image":"art/canvas","audio":""},{"speaker":"Mimi","text":"My book is open.","translation":"我的书打开了。","scene":"英语课堂","image":"art/canvas","audio":""},{"speaker":"Teacher","text":"Great! Please line up.","translation":"很好！请排队。","scene":"英语课堂","image":"art/canvas","audio":""}]}', 7, 3),
(502, 44, '说出我的心情', 'DIALOGUE', '{"type":"DIALOGUE","scene":"心情角","tip":"练习表达情绪并回应关心","items":[{"speaker":"Friend","text":"How do you feel?","translation":"你感觉怎么样？","scene":"心情角","image":"emotion/confide","audio":""},{"speaker":"Mimi","text":"I feel a little sad.","translation":"我有一点难过。","scene":"心情角","image":"emotion/confide","audio":""},{"speaker":"Friend","text":"Do you want a hug?","translation":"你想要一个拥抱吗？","scene":"心情角","image":"emotion/confide","audio":""},{"speaker":"Mimi","text":"Yes, please. Thank you.","translation":"想要，谢谢你。","scene":"心情角","image":"emotion/confide","audio":""},{"speaker":"Mimi","text":"I feel better now.","translation":"我现在感觉好多了。","scene":"心情角","image":"emotion/confide","audio":""}]}', 6, 3),
(503, 44, '我不舒服怎么办', 'DIALOGUE', '{"type":"DIALOGUE","scene":"健康与安全","tip":"练习表达身体不适并寻求成人帮助","items":[{"speaker":"Mimi","text":"My tummy hurts.","translation":"我的肚子疼。","scene":"健康与安全","image":"career/doctor","audio":""},{"speaker":"Teacher","text":"Please sit down and rest.","translation":"请坐下来休息。","scene":"健康与安全","image":"career/doctor","audio":""},{"speaker":"Mimi","text":"I need help, please.","translation":"我需要帮助。","scene":"健康与安全","image":"career/doctor","audio":""},{"speaker":"Teacher","text":"I will call your family.","translation":"我会联系你的家人。","scene":"健康与安全","image":"career/doctor","audio":""},{"speaker":"Mimi","text":"Thank you. I will wait here.","translation":"谢谢。我会在这里等。","scene":"健康与安全","image":"career/doctor","audio":""}]}', 7, 3);
INSERT INTO lesson (id, unit_id, name, type, content, sort_order, star_reward) VALUES
(504, 39, '动物复习·听与认', 'QUIZ', '{"type":"QUIZ","items":[{"activity":"LISTEN_IMAGE","question":"听一听，选出正确图片","audioText":"puppy","audioLanguage":"en","image":"pet/playing","options":[{"text":"puppy","image":"pet/puppy","showText":false},{"text":"kitten","image":"pet/kitten","showText":false},{"text":"rabbit","image":"pet/rabbit","showText":false}],"answer":0},{"activity":"IMAGE_WORD","question":"图片里的动物用英语怎么说？","image":"pet/kitten","options":["cat","dog","rabbit"],"answer":0},{"activity":"SENTENCE_COMPLETION","question":"补全句子：I see a ___.","image":"pet/rabbit","options":["rabbit","fish","fox"],"answer":0},{"activity":"CATEGORY","question":"小狗属于哪一类？","image":"pet/puppy","options":["pet","food","weather"],"answer":0},{"activity":"SITUATION","question":"看到一只小狗，可以怎么说？","image":"pet/walking","options":["It is a puppy.","I like milk.","Open the book."],"answer":0}]}', 6, 3),
(505, 40, '动物复习·森林挑战', 'QUIZ', '{"type":"QUIZ","items":[{"activity":"LISTEN_IMAGE","question":"听一听，选出正确图片","audioText":"fox","audioLanguage":"en","image":"story/fox-tiger-2","options":[{"text":"fox","image":"story/fox-tiger-1","showText":false},{"text":"rabbit","image":"pet/rabbit","showText":false},{"text":"puppy","image":"pet/puppy","showText":false}],"answer":0},{"activity":"IMAGE_WORD","question":"图片里的动物是什么？","image":"pet/rabbit","options":["rabbit","fox","cat"],"answer":0},{"activity":"SENTENCE_COMPLETION","question":"补全句子：The fox can ___.","image":"story/fox-tiger-1","options":["run","drink","read"],"answer":0},{"activity":"CATEGORY","question":"狐狸属于哪一类动物？","image":"story/fox-tiger-2","options":["wild animal","pet","farm tool"],"answer":0},{"activity":"SITUATION","question":"在森林里看到狐狸，可以怎么提醒同伴？","image":"story/fox-tiger-3","options":["Look, a fox!","Here is a spoon.","I am at school."],"answer":0}]}', 6, 3),
(506, 41, '家庭复习·温暖表达', 'QUIZ', '{"type":"QUIZ","items":[{"activity":"LISTEN_IMAGE","question":"听一听，选出符合意思的图片","audioText":"hug","audioLanguage":"en","image":"emotion/encourage","options":[{"text":"hug","image":"emotion/hug","showText":false},{"text":"sad","image":"emotion/sad","showText":false},{"text":"angry","image":"emotion/angry","showText":false}],"answer":0},{"activity":"IMAGE_WORD","question":"这幅图表达哪个单词？","image":"emotion/hug","options":["hug","run","cook"],"answer":0},{"activity":"SENTENCE_COMPLETION","question":"补全句子：I love my ___.","image":"emotion/hug","options":["family","weather","train"],"answer":0},{"activity":"CATEGORY","question":"mother、father、sister 属于哪一类？","image":"festival/childrens-day","options":["family","food","animals"],"answer":0},{"activity":"SITUATION","question":"家人帮助了你，应该怎么说？","image":"emotion/encourage","options":["Thank you!","Go away!","I am a cat."],"answer":0}]}', 7, 3),
(507, 42, '校园复习·课堂行动', 'QUIZ', '{"type":"QUIZ","items":[{"activity":"LISTEN_IMAGE","question":"听一听，选出正确图片","audioText":"crayon","audioLanguage":"en","image":"art/canvas","options":[{"text":"crayon","image":"art/crayon","showText":false},{"text":"canvas","image":"art/canvas","showText":false},{"text":"coloring","image":"art/coloring","showText":false}],"answer":0},{"activity":"IMAGE_WORD","question":"图片里的物品是什么？","image":"art/crayon","options":["crayon","spoon","shoe"],"answer":0},{"activity":"SENTENCE_COMPLETION","question":"补全指令：Open your ___.","image":"math/pencil-9","options":["book","milk","dog"],"answer":0},{"activity":"CATEGORY","question":"pencil、crayon、book 属于哪一类？","image":"art/coloring","options":["school things","animals","food"],"answer":0},{"activity":"SITUATION","question":"老师说 Please line up，你应该做什么？","image":"sports/relay","options":["排队","睡觉","吃早餐"],"answer":0}]}', 8, 3),
(508, 43, '身体复习·动一动', 'QUIZ', '{"type":"QUIZ","items":[{"activity":"LISTEN_IMAGE","question":"听一听，选出正确图片","audioText":"smile","audioLanguage":"en","image":"emotion/encourage","options":[{"text":"smile","image":"emotion/smile","showText":false},{"text":"sad","image":"emotion/sad","showText":false},{"text":"angry","image":"emotion/angry","showText":false}],"answer":0},{"activity":"IMAGE_WORD","question":"这幅图表示哪个动作？","image":"sports/running","options":["run","sleep","eat"],"answer":0},{"activity":"SENTENCE_COMPLETION","question":"补全句子：I can ___ with my legs.","image":"sports/running","options":["run","listen","smell"],"answer":0},{"activity":"CATEGORY","question":"eye、ear、nose 属于哪一类？","image":"career/doctor","options":["body parts","food","clothes"],"answer":0},{"activity":"SITUATION","question":"运动前应该做什么？","image":"sports/balance-beam","options":["Warm up.","Go to sleep.","Eat candy."],"answer":0}]}', 6, 3),
(509, 44, '健康复习·照顾自己', 'QUIZ', '{"type":"QUIZ","items":[{"activity":"LISTEN_IMAGE","question":"听一听，选出正确图片","audioText":"doctor","audioLanguage":"en","image":"emotion/encourage","options":[{"text":"doctor","image":"career/doctor","showText":false},{"text":"pilot","image":"career/pilot","showText":false},{"text":"chef","image":"career/chef","showText":false}],"answer":0},{"activity":"IMAGE_WORD","question":"图中的心情是什么？","image":"emotion/sad","options":["sad","happy","surprised"],"answer":0},{"activity":"SENTENCE_COMPLETION","question":"补全句子：Drink some ___.","image":"plant/water","options":["water","sand","paint"],"answer":0},{"activity":"CATEGORY","question":"wash、brush、sleep 属于哪一类？","image":"pet/cleaning","options":["healthy habits","animals","weather"],"answer":0},{"activity":"SITUATION","question":"身体不舒服时应该怎么办？","image":"career/doctor","options":["Tell an adult.","Hide alone.","Keep running."],"answer":0}]}', 8, 3),
(510, 47, '食物复习·早餐时间', 'QUIZ', '{"type":"QUIZ","items":[{"activity":"LISTEN_IMAGE","question":"听一听，选出正确图片","audioText":"apple","audioLanguage":"en","image":"plant/apple-tree","options":[{"text":"apple","image":"math/apple-1","showText":false},{"text":"egg","image":"math/egg-7","showText":false},{"text":"candy","image":"math/candy-8","showText":false}],"answer":0},{"activity":"IMAGE_WORD","question":"图片里的食物是什么？","image":"plant/tomato","options":["tomato","carrot","apple"],"answer":0},{"activity":"SENTENCE_COMPLETION","question":"补全句子：I like ___.","image":"math/strawberry-6","options":["strawberries","spoons","books"],"answer":0},{"activity":"CATEGORY","question":"apple、carrot、tomato 属于哪一类？","image":"plant/carrot","options":["food","clothes","transport"],"answer":0},{"activity":"SITUATION","question":"想要一个苹果，可以怎么说？","image":"math/apple-1","options":["I want an apple, please.","I am an apple.","Open the apple."],"answer":0}]}', 7, 3),
(511, 48, '餐桌复习·礼貌用餐', 'QUIZ', '{"type":"QUIZ","items":[{"activity":"LISTEN_IMAGE","question":"听一听，选出正确图片","audioText":"water","audioLanguage":"en","image":"science/water-states","options":[{"text":"water","image":"plant/water","showText":false},{"text":"carrot","image":"plant/carrot","showText":false},{"text":"tomato","image":"plant/tomato","showText":false}],"answer":0},{"activity":"IMAGE_WORD","question":"图片中的人物是谁？","image":"career/chef","options":["chef","teacher","pilot"],"answer":0},{"activity":"SENTENCE_COMPLETION","question":"补全句子：Please pass the ___.","image":"plant/carrot","options":["carrots","shoes","clouds"],"answer":0},{"activity":"CATEGORY","question":"plate、bowl、spoon 属于哪一类？","image":"career/chef","options":["tableware","animals","weather"],"answer":0},{"activity":"SITUATION","question":"吃完饭后应该怎么做？","image":"pet/cleaning","options":["Say thank you and tidy up.","Throw food.","Run away."],"answer":0}]}', 6, 3);
